from flask import Flask, request

app = Flask(__name__)

@app.route('/about')
def about():
    bio = request.args.get('bio')
    location = request.args.get('location')

    response = '''
    <h1> About </h1>
    {}
    '''.format(bio)

    return response

if __name__ == '__main__':
    app.run()
